/** The particulars of the manual's form. On the first save Haspataal pre-fills what it knows (the incident's medicine, the batch named by `batch_id`, the date it was reported); the fields sent override it. */
export interface AdrReportIn {
  /** A stock batch of the medicine: fills the batch number and expiry (GET /drugs/{drug_id}/stock-status) */
  batch_id?: number | null;
  complaint_received_on?: string | null;
  complaint_source?: "Patient" | "Attendant" | "SelfInspection" | "Other" | null;
  /** Required when the source is Other */
  complaint_source_other?: string | null;
  similar_reports?: number | null;
  /** The results of tests attached, if any */
  tests_attached?: string | null;
  manufacturer_contacted?: boolean | null;
  manufacturer_contact_details?: string | null;
  product_name?: string | null;
  /** With their strength */
  active_ingredients?: string | null;
  pack_size?: string | null;
  /** The DRAP registration number on the pack */
  registration_number?: string | null;
  dosage_form?: string | null;
  batch_number?: string | null;
  expiry_date?: string | null;
  manufacture_date?: string | null;
  manufacturer_name?: string | null;
  manufacturer_address?: string | null;
  manufacturer_phone?: string | null;
  manufacturer_fax?: string | null;
  /** Optimistic concurrency: the row_version you loaded */
  expected_version?: number | null;
}

export interface AdrSendIn {
  recipient: "DRAP" | "Manufacturer" | "Supplier";
  sent_on: string;
  /** DRAP's acknowledgement number, the e-mail or letter */
  reference?: string | null;
}

