/** The incident register — GET /api/v1/incidents (who may call: holders of incident.view or incident.report or ot.clinical_statistics.view). */
export function listIncidents(query?: { status?: "Reported" | "UnderReview" | "Analysed" | "Closed" | "Withdrawn" | null; type_code?: string | null; area?: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational" | null; sentinel_only?: boolean; harm?: "NoHarm" | "Mild" | "Moderate" | "Severe" | "Death" | null; department_id?: number | null; booking_id?: number | null; patient_id?: number | null; date_from?: string | null; date_to?: string | null; mine?: boolean; open_only?: boolean; limit?: number }): Promise<IncidentOut[]> {
  return api<IncidentOut[]>("GET", withQuery(`/incidents`, query), undefined);
}

/** An adverse drug reaction's report (or its pre-filled draft) — GET /api/v1/incidents/{incident_id}/adr-report (who may call: holders of incident.view or incident.manage). */
export function getIncidentsAdrReport(incident_id: number): Promise<AdrReportOut> {
  return api<AdrReportOut>("GET", `/incidents/${incident_id}/adr-report`, undefined);
}

/** Save the ADR report (the manual's format) — PUT /api/v1/incidents/{incident_id}/adr-report (who may call: holders of incident.manage). */
export function save(incident_id: number, body: AdrReportIn): Promise<AdrReportOut> {
  return api<AdrReportOut>("PUT", `/incidents/${incident_id}/adr-report`, body);
}

/** Record that the ADR report was sent — POST /api/v1/incidents/{incident_id}/adr-report/submissions (who may call: holders of incident.manage). */
export function send(incident_id: number, body: AdrSendIn): Promise<AdrReportOut> {
  return api<AdrReportOut>("POST", `/incidents/${incident_id}/adr-report/submissions`, body, { idempotent: true });
}

/** The ADR report in the manual's format (PDF) — GET /api/v1/incidents/{incident_id}/adr-report/pdf (who may call: holders of incident.view or incident.manage). */
export function pdf(incident_id: number): Promise<unknown> {
  return api<unknown>("GET", `/incidents/${incident_id}/adr-report/pdf`, undefined);
}

/** One incident — GET /api/v1/incidents/{incident_id} (who may call: incident.view, the reporter and the investigator; ot.clinical_statistics.view for theatre adverse events). */
export function getIncident(incident_id: number): Promise<IncidentDetailOut> {
  return api<IncidentDetailOut>("GET", `/incidents/${incident_id}`, undefined);
}

/** Drug stock with batches in FEFO order — GET /api/v1/drugs/{drug_id}/stock-status (who may call: holders of pharmacy.formulary.view or pharmacy.stock.view). */
export function stockStatus(drug_id: number): Promise<DrugStockDetailOut> {
  return api<DrugStockDetailOut>("GET", `/drugs/${drug_id}/stock-status`, undefined);
}
